INSERT INTO public.past_events (id, title, spotlight_text, description, image_url, tags, is_active, created_at, updated_at) VALUES ('d41f2730-e242-4772-b4de-9fc197ab4df9', 'Royal Waffle Creator Event', 'March 2026', 'This March, Waffle Castle hosted an exclusive creator collaboration event, bringing together talented food and lifestyle creators for a royal experience. From indulgent waffle tastings to high-energy content creation, the event turned into a celebration of creativity, community, and delicious moments. Creators competed to win the prestigious Royal Crown, with entries judged on views, engagement, and creativity, making it one of the most exciting creator events in the city.', '/images/1779880592239-waffle-main.png', ARRAY['#RoyalWaffleDay  #WaffleCastle  #FoodCreators'], true, '2026-05-26 09:22:53.791102+00', '2026-07-01 09:02:26.823387+00');